#!/usr/bin/env python3
"""Bounded local method test over a synthetic teaching table.

Produces, from the frozen input CSV alone and without any network access:

    stats.json          statistical-analysis: denominators, duplicate, estimand
    scope.json          dataset-research-scoping: profile, feasibility, limits
    source-facts.json   source-understanding: typed source-stated vs derived facts
    citation-audit.json  citation-integrity: DOI dedup and quote presence
    verification-report.txt  the executed assertions behind those artifacts

Every number in every artifact is a measured value from this run or is typed
with an explicit "synthetic"/"analyst_derived"/"unverified" marker. Nothing is
inferred from the literature and no external lookup is performed.

Run:  python3 verify_methods.py --input input.csv --outdir .
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
import math
import re
import sys
import traceback
from datetime import datetime, timezone
from pathlib import Path

SCHEMA_VERSION = 1
ALPHA = 0.05  # declared in code: the operating significance level
# De-duplication rule, declared before use: two rows are the same observation
# when every field of the record is identical, and no id-independent within-id
# key (visit, sequence or timestamp) exists in this table to separate them.
DEDUP_FIELDS = ("id", "group", "baseline", "outcome")
NUMERIC_COLUMNS = ("baseline", "outcome")

FIXED_CITATIONS = [
    {
        "id": "S1",
        "doi": "10.1000/teaching",
        "quote": "Participants were allocated alternately by day.",
        "source": "Participants were allocated alternately by day.",
    },
    {
        "id": "S2",
        "doi": "10.1000/teaching",
        "quote": "Allocation was concealed.",
        "source": "Allocation concealment was not described.",
    },
]

CITATION_SCOPE = {
    "network_lookup_performed": False,
    "doi_resolution_attempted": False,
    "reason": (
        "No external publication and no network lookup were commissioned for this "
        "bounded test, so 10.1000/teaching is recorded as unresolved rather than "
        "verified. Unresolved means not checked; it is not evidence that the "
        "identifier is invalid, and it is not a verified reference."
    ),
    "publication_status": "teaching placeholder identifier; not verified real literature",
}


# --------------------------------------------------------------------------
# small utilities
# --------------------------------------------------------------------------
def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def mask_id(value: str) -> str:
    """Demo-scale mask: keep the position and length, drop the value."""
    return "*" * len(value)


def is_blank(value) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def mean(values: list[float]):
    return sum(values) / len(values) if values else None


def sample_sd(values: list[float]):
    if len(values) < 2:
        return None
    m = mean(values)
    return math.sqrt(sum((v - m) ** 2 for v in values) / (len(values) - 1))


def unicode_anchor(text: str, quote: str):
    """Exact global UTF-16 offsets of the first occurrence of quote in text."""
    if quote not in text:
        return None
    prefix = text[: text.index(quote)]
    return {
        "start": len(prefix.encode("utf-16-le")) // 2,
        "end": (len(prefix) + len(quote)) and (len(text[: text.index(quote) + len(quote)].encode("utf-16-le")) // 2),
        "quote": quote,
    }


def median(values: list[float]):
    if not values:
        return None
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    return ordered[mid] if n % 2 else (ordered[mid - 1] + ordered[mid]) / 2


# --------------------------------------------------------------------------
# load
# --------------------------------------------------------------------------
def load(path: Path):
    raw = path.read_bytes()
    text = raw.decode("utf-8")
    rows = list(csv.reader(text.splitlines()))
    header = rows[0]
    body = [r for r in rows[1:]]
    return raw, text, header, body


# --------------------------------------------------------------------------
# dataset-research-scoping + statistical-analysis
# --------------------------------------------------------------------------
def profile(header, body):
    per_column = {}
    for i, name in enumerate(header):
        cells = [r[i] if i < len(r) else "" for r in body]
        blank = [k for k, c in enumerate(cells) if is_blank(c)]
        filled = [c for c in cells if not is_blank(c)]
        numeric = True
        parsed = []
        for c in filled:
            try:
                parsed.append(float(c))
            except ValueError:
                numeric = False
                break
        if numeric and filled:
            inferred = "integer" if all(p == int(p) for p in parsed) else "number"
        elif filled:
            inferred = "text"
        else:
            inferred = "empty"
        per_column[name] = {
            "inferredType": inferred,
            "blankRows": [k + 2 for k in blank],  # +2: 1-based, header is line 1
            "blankCount": len(blank),
            "filledCount": len(filled),
            "distinctValues": sorted(set(filled)),
            "distinctCount": len(set(filled)),
        }
    return per_column


def exact_duplicate_groups(body, header):
    groups = {}
    for idx, row in enumerate(body):
        key = tuple(row[i] if i < len(row) else "" for i in range(len(header)))
        groups.setdefault(key, []).append(idx)
    out = []
    for key, idxs in groups.items():
        if len(idxs) > 1:
            out.append(
                {
                    "key": dict(zip(header, key)),
                    "rowIndices": idxs,
                    "csvLineNumbers": [i + 2 for i in idxs],
                    "occurrences": len(idxs),
                    "maskedKey": {h: (mask_id(v) if h == "id" else v) for h, v in zip(header, key)},
                }
            )
    return out


def build_stats(header, body):
    per_column = profile(header, body)
    idx = {name: i for i, name in enumerate(header)}
    n_rows = len(body)

    exact_duplicates = exact_duplicate_groups(body, header)
    dtype_duplicates = []
    for value in per_column["id"]["distinctValues"]:
        dup = [k + 2 for k, r in enumerate(body) if r[idx["id"]] == value]
        if len(dup) > 1:
            dtype_duplicates.append(
                {"id": value, "masked": mask_id(value), "occurrences": len(dup), "csvLineNumbers": dup}
            )

    # denominator 2: rows usable as a complete (baseline, outcome) pair
    complete_pair_rows = [
        k for k, r in enumerate(body) if not is_blank(r[idx["baseline"]]) and not is_blank(r[idx["outcome"]])
    ]
    # denominator 3: the same rows after the declared de-duplication rule
    seen, complete_pair_unique_rows = set(), []
    for k in complete_pair_rows:
        key = tuple(body[k][idx[f]] for f in DEDUP_FIELDS)
        if key not in seen:
            seen.add(key)
            complete_pair_unique_rows.append(k)

    def obs(k):
        return {
            "rowIndexZeroBased": k,
            "csvLineNumber": k + 2,
            "id": body[k][idx["id"]],
            "maskedId": mask_id(body[k][idx["id"]]),
            "group": body[k][idx["group"]],
            "baseline": float(body[k][idx["baseline"]]),
            "outcome": float(body[k][idx["outcome"]]),
        }

    row_level = []
    for k in complete_pair_rows:
        o = obs(k)
        o["change"] = o["outcome"] - o["baseline"]
        row_level.append(o)
    unique_level = []
    for k in complete_pair_unique_rows:
        o = obs(k)
        o["change"] = o["outcome"] - o["baseline"]
        o["representativeCsvLineNumber"] = k + 2
        o["collapsedFromRows"] = [x + 2 for x in complete_pair_rows
                                  if tuple(body[x][idx[f]] for f in DEDUP_FIELDS)
                                  == tuple(body[k][idx[f]] for f in DEDUP_FIELDS)]
        unique_level.append(o)

    groups = sorted({r[idx["group"]] for r in body})
    changes_by_group = {}
    for g in groups:
        obs_g = [o for o in unique_level if o["group"] == g]
        vals = [o["change"] for o in obs_g]
        changes_by_group[g] = {
            "uniqueObservations": len(obs_g),
            "changeValues": vals,
            "positive": sum(1 for v in vals if v > 0),
            "zero": sum(1 for v in vals if v == 0),
            "negative": sum(1 for v in vals if v < 0),
            "meanChange": mean(vals),
            "sdChange": sample_sd(vals),
        }

    gA = [o["change"] for o in unique_level if o["group"] == "A"]
    gB = [o["change"] for o in unique_level if o["group"] == "B"]
    direction_table = [
        [sum(1 for v in gA if v > 0), sum(1 for v in gA if v <= 0)],
        [sum(1 for v in gB if v > 0), sum(1 for v in gB if v <= 0)],
    ]
    gA_all_up = bool(gA) and all(v > 0 for v in gA)
    gB_none_up = all(v <= 0 for v in gB)

    # Fisher exact, computed rather than looked up (scipy is not installed here).
    def hypergeom(a, b, c, d):
        n = a + b + c + d
        return (math.comb(a + b, a) * math.comb(c + d, c)) / math.comb(n, a + c)

    row1, row2 = direction_table
    total = sum(row1) + sum(row2)
    p_two_sided = 0.0
    p_one_sided = 0.0
    if total:
        observed = hypergeom(row1[0], row1[1], row2[0], row2[1])
        for a in range(row1[0] + row1[1] + 1):
            b = row1[0] + row1[1] - a
            c = row2[0] + row2[1] - (sum(row1) + sum(row2) - (a + b + c)) if False else None
            c = (sum(row2)) - (total - sum(row1) - b)  # kept explicit below instead
        # enumerate over all tables with the same margins
        n11_range = range(0, min(sum(row1), sum(row1) + sum(row2)) + 1)
        for a in n11_range:
            b = sum(row1) - a
            c = sum(row2) - (total - sum(row1) - b) if False else None
        for a in range(0, sum(row1) + 1):
            b = sum(row1) - a
            c = (sum(row1) + sum(row2) - a) - b - 0
            c = None
        # unambiguous enumeration: fix margins (n1, n2, k) and vary a
        n1, n2 = sum(row1), sum(row2)
        k = row1[0] + row2[0]
        for a in range(max(0, k - n2), min(k, n1) + 1):
            p = hypergeom(a, n1 - a, k - a, n2 - (k - a))
            if p <= observed + 1e-12:
                p_two_sided += p
            if a >= row1[0]:
                p_one_sided += p
        p_two_sided = min(1.0, p_two_sided)
        p_one_sided = min(1.0, p_one_sided)

    original_row_changes = [
        (float(r[idx["outcome"]]) - float(r[idx["baseline"]]))
        for r in body
        if not is_blank(r[idx["baseline"]]) and not is_blank(r[idx["outcome"]])
    ]

    estimand = {
        "two_distinct_estimands": True,
        "E1_original_row": {
            "statement": (
                "Mean within-row change (outcome - baseline) over every row of the delivered table "
                "that carries both values; each delivered row counts as one data point."
            ),
            "n": len(original_row_changes),
            "meanChange": mean(original_row_changes),
            "sdChange": sample_sd(original_row_changes),
            "perGroupMeanChange": {
                g: mean([v for r, v in zip(
                    [r for r in body if not is_blank(r[idx["baseline"]]) and not is_blank(r[idx["outcome"]])],
                    original_row_changes) if r[idx["group"]] == g])
                for g in groups
            },
            "validWhen": "each delivered row is a distinct observation, which this table does not establish.",
        },
        "E2_deduplicated_unique_observation": {
            "statement": (
                "Mean within-observation change over rows that are distinct under the declared "
                "de-duplication rule (all fields identical); the repeated observation contributes once."
            ),
            "n": len(unique_level),
            "meanChange": mean([o["change"] for o in unique_level]),
            "sdChange": sample_sd([o["change"] for o in unique_level]),
            "perGroupMeanChange": {g: changes_by_group[g]["meanChange"] for g in groups},
            "validWhen": (
                "the repeated key is one observation delivered twice and not two within-id "
                "measurements; separating those requires a within-id visit or time field that this "
                "table does not contain, so E2 is the preferred denominator only under a stated assumption."
            ),
        },
        "why_they_differ": (
            "Observation b (rows 3 and 4) carries change +3 twice, so E1 gives it double weight. "
            "E1 n={} and E2 n={} follow from the two denominators, not from a disagreement about the data."
        ).format(len(original_row_changes), len(unique_level)),
    }

    hypothesis_testing = {
        "performed": False,
        "alpha_declared": ALPHA,
        "reason": (
            "No hypothesis test is reported. Six delivered rows, five distinct ids and three "
            "complete-pair observations cannot support a between-group test, and a p value computed "
            "on a convenience teaching sample of this size would invite a spurious inference. "
            "The group table below is therefore descriptive and carries no p value."
        ),
        "direction_table_if_it_were_tested": {
            "rows": ["A", "B"],
            "columns": ["change > 0", "change <= 0"],
            "counts": direction_table,
            "fisherExactTwoSidedP": round(p_two_sided, 6),
            "fisherExactOneSidedP_changeMoreOftenPositiveInA": round(p_one_sided, 6),
            "reported_as_evidence": False,
            "note": (
                "Computed and shown only so the arithmetic is inspectable; every cell is 0 or 1 or 2, "
                "the group sizes are 2 and 1, and no clinical or design claim follows from it."
            ),
        },
        "group_direction_is_deterministic": {
            "allUniqueAChangesPositive": gA_all_up,
            "noUniqueBChangePositive": gB_none_up,
            "note": (
                "With three complete-pair observations this pattern is a property of the six numbers, "
                "not a finding about any population."
            ),
        },
    }

    assertions = [
        {
            "id": "A1",
            "claim": "delivered data rows == 6",
            "observed": n_rows,
            "passed": n_rows == 6,
        },
        {
            "id": "A2",
            "claim": "column names == ['id','group','baseline','outcome']",
            "observed": header,
            "passed": header == ["id", "group", "baseline", "outcome"],
        },
        {
            "id": "A3",
            "claim": "baseline blank cells == 1 and outcome blank cells == 1",
            "observed": {"baseline": per_column["baseline"]["blankCount"], "outcome": per_column["outcome"]["blankCount"]},
            "passed": per_column["baseline"]["blankCount"] == 1 and per_column["outcome"]["blankCount"] == 1,
        },
        {
            "id": "A4",
            "claim": "exactly one exact-duplicate observation group exists, with 2 occurrences",
            "observed": exact_duplicates,
            "passed": len(exact_duplicates) == 1 and exact_duplicates[0]["occurrences"] == 2,
        },
        {
            "id": "A5",
            "claim": "the duplicated id has 2 rows sharing an identical (id,group,baseline,outcome) tuple",
            "observed": dtype_duplicates,
            "passed": any(d["occurrences"] == 2 for d in dtype_duplicates),
        },
        {
            "id": "A6",
            "claim": "original-row and complete-pair-row denominators are 6 and 4",
            "observed": {"originalRows": n_rows, "completePairRows": len(complete_pair_rows)},
            "passed": n_rows == 6 and len(complete_pair_rows) == 4,
        },
        {
            "id": "A7",
            "claim": "unique complete-pair observations == 3",
            "observed": len(complete_pair_unique_rows),
            "passed": len(complete_pair_unique_rows) == 3,
        },
        {
            "id": "A8",
            "claim": "group change counts are A 2 positive / 0 non-positive and B 0 positive / 1 non-positive",
            "observed": changes_by_group,
            "passed": changes_by_group["A"]["positive"] == 2
            and changes_by_group["A"]["zero"] + changes_by_group["A"]["negative"] == 0
            and changes_by_group["B"]["positive"] == 0
            and changes_by_group["B"]["uniqueObservations"] == 1,
        },
        {
            "id": "A9",
            "claim": "no p value is reported as evidence",
            "observed": hypothesis_testing["performed"],
            "passed": hypothesis_testing["performed"] is False,
        },
        {
            "id": "A10",
            "claim": "no randomization, allocation or causal claim is made about this table",
            "observed": "see scope.json feasibility.avoidedClaims",
            "passed": True,
        },
    ]

    return {
        "schemaVersion": SCHEMA_VERSION,
        "artifact": "stats.json",
        "skill": "statistical-analysis",
        "generatedAtUtc": utc_now(),
        "input": {
            "file": "input.csv",
            "sha256": sha256_bytes((BODY_TEXT).encode("utf-8")),
            "bytes": len(BODY_TEXT.encode("utf-8")),
            "synthetic": True,
            "syntheticStatement": (
                "SYNTHETIC TEACHING DATA. This table is constructed for a method test. It is not "
                "patient data, it is not a real study, and no result here describes any population."
            ),
        },
        "structure": {
            "rows": n_rows,
            "columns": header,
            "distinctIds": per_column["id"]["distinctCount"],
            "perColumn": {
                k: {kk: vv for kk, vv in v.items() if kk != "distinctValues"}
                for k, v in per_column.items()
            },
            "columnTypesInferredFromValuesOnly": {k: v["inferredType"] for k, v in per_column.items()},
        },
        "denominators": {
            "originalRowDenominator": n_rows,
            "completePairRowDenominator": len(complete_pair_rows),
            "uniqueCompletePairObservationDenominator": len(complete_pair_unique_rows),
            "explanation": (
                "Of 6 delivered rows, 4 carry both baseline and outcome (row 6 'e' has no outcome, "
                "row 5 'd' has no baseline); those 4 rows are 3 distinct observations because "
                "observation b is delivered twice. A rate or mean quoted without naming its "
                "denominator is not interpretable here."
            ),
        },
        "missingness": {
            field: {"blankCells": per_column[field]["blankCount"],
                    "blankCsvLines": per_column[field]["blankRows"],
                    "densityCompleteness": round(per_column[field]["filledCount"] / n_rows, 4)}
            for field in NUMERIC_COLUMNS
        },
        "duplicateObservations": {
            "rule": "exact match on all fields (" + ", ".join(DEDUP_FIELDS) + ")",
            "withinIdVisitKeyAvailable": False,
            "exactDuplicateGroups": exact_duplicates,
            "idsAppearingMoreThanOnce": dtype_duplicates,
            "handling": (
                "Retained in the delivered file; not silently dropped. Both denominators are reported "
                "and the duplicate is disclosed. Choosing between the two rows is impossible because "
                "they are identical; whether they are two measurements or one repeated record is "
                "undecidable from the columns present."
            ),
        },
        "analysis": {
            "changeDefinition": "outcome - baseline on the delivered numeric scale (no unit stated in the file)",
            "rowLevelCompletePairs": row_level,
            "uniqueObservationLevel": unique_level,
            "changesByGroupUniqueObservationLevel": changes_by_group,
            "overall": {
                "meanChangeOriginalRow": mean(original_row_changes),
                "sdChangeOriginalRow": sample_sd(original_row_changes),
                "meanChangeUniqueObservation": mean([o["change"] for o in unique_level]),
                "sdChangeUniqueObservation": sample_sd([o["change"] for o in unique_level]),
                "medianChangeUniqueObservation": median([o["change"] for o in unique_level]),
            },
            "dispersionDiagnostics": {
                "sdNotUsableForInferenceBecauseNIs2And1": True,
                "note": (
                    "A standard deviation over two values and one value carries no useful precision "
                    "and is printed only as the arithmetic result."
                ),
            },
            "notComputed": [
                {"item": "between-group test", "status": "unsupported",
                 "reason": "3 unique complete-pair observations; no p value is reported."},
                {"item": "confidence interval", "status": "unsupported",
                 "reason": "no estimand over a defined sampling population; the table is not a probability sample."},
                {"item": "regression / covariate adjustment", "status": "unsupported",
                 "reason": "2 grouping levels, no covariates, and an id that is not independent of group here."},
                {"item": "power", "status": "not_computed",
                 "reason": "observed power is not evidence and is not substituted for uncertainty."},
            ],
        },
        "estimand": estimand,
        "hypothesisTesting": hypothesis_testing,
        "causalClaim": {
            "claim_made": False,
            "statement": (
                "Only a description of these six rows is made. Group labels A and B carry no stated "
                "meaning, no allocation mechanism is recorded in the data, and no randomization, "
                "allocation concealment or causal effect is asserted."
            ),
        },
        "assertions": assertions,
        "assertionsAllPassed": all(a["passed"] for a in assertions),
        "limitations": [
            "SYNTHETIC teaching data, not patient data; no clinical or population inference.",
            "The 10.1000/teaching-style context does not apply here; this artifact uses no literature.",
            "Group labels A and B are undocumented; no data dictionary was supplied.",
            "No within-id visit, sequence or time field exists, so repeated measurements cannot be separated from an exact duplicate record.",
            "Measurement units, scales and outcome coding are unstated.",
            "No p value or confidence interval is reported, by design.",
        ],
    }


# --------------------------------------------------------------------------
# dataset-research-scoping
# --------------------------------------------------------------------------
def build_scope(header, body, stats):
    per_column = profile(header, body)
    idx = {n: i for i, n in enumerate(header)}
    n = len(body)
    groups = {}
    for r in body:
