def run_assertions(stats, scope, facts, audit):
    results = [dict(a) for a in stats["assertions"]]

    extra = []

    def check(cid, claim, observed, passed):
        extra.append({"id": cid, "claim": claim, "observed": observed, "passed": bool(passed)})

    dup = scope["duplicateObservation"]["groups"]
    dup_ids = sorted({g["key"]["id"] for g in dup})
    check("A11", "scope.json reports exactly one duplicated observation label",
          {"duplicateGroups": len(dup), "labels": dup_ids},
          len(dup) == 1 and len(dup_ids) == 1)
    check("A12", "scope.json reports 1 baseline blank and 1 outcome blank, naming their lines",
          scope["missingness"],
          scope["missingness"]["baseline"]["blankCells"] == 1
          and scope["missingness"]["outcome"]["blankCells"] == 1)
    check("A13", "scope.json states the dictionary evidence is weak and gives no randomization claim",
          {"strength": scope["dictionaryEvidence"]["strength"],
           "avoidedClaims": len(scope["feasibility"]["avoidedClaims"])},
          scope["dictionaryEvidence"]["strength"] == "weak"
          and any("randomi" in c.lower() for c in scope["feasibility"]["avoidedClaims"]))
    check("A14", "scope.json records the evidence map as not_run rather than empty-and-clean",
          scope["evidenceMap"]["status"], scope["evidenceMap"]["status"] == "not_run")

    anchor_ok = []
    for fact in facts["sourceStatedFacts"]:
        for ev in fact["evidence"]:
            ok = (ev is not None
                  and ev["quote"] in facts_source_text
                  and facts_source_text[ev["start"]:ev["end"]] == ev["quote"]
                  or (ev is not None and ev["quote"] in facts_source_text
                      and len(facts_source_text[:ev["start"]].encode("utf-16-le")) // 2 == ev["start"]
                      and facts_source_text[ev["start"]:ev["end"]] == ev["quote"]))
            anchor_ok.append(ok)
    check("A15", "every source-stated fact carries an anchor whose quote resolves inside the frozen text",
          {"facts": len(facts["sourceStatedFacts"]), "anchors": len(anchor_ok), "allResolve": all(anchor_ok)},
          anchor_ok and all(anchor_ok))
    check("A16", "source-facts.json separates source-stated facts from analyst-derived ones",
          {"sourceStated": len(facts["sourceStatedFacts"]),
           "analystDerivedOrInferred": len(facts["analystDerivedAndInferredFacts"])},
          len(facts["sourceStatedFacts"]) > 0 and len(facts["analystDerivedAndInferredFacts"]) > 0
          and all(f["evidence"] for f in facts["sourceStatedFacts"]))
    check("A17", "source-facts.json marks the source synthetic in explicit terms",
          facts["syntheticStatus"]["statement"][:60] + "...",
          facts["syntheticStatus"]["synthetic"] is True
          and "synthetic" in facts["syntheticStatus"]["statement"].lower())
    check("A18", "no omission rate is claimed without an audit sample",
          facts["omissionAudit"],
          facts["omissionAudit"]["status"] == "not_run" and facts["omissionAudit"]["omissionRate"] is None)

    check("A19", "citation audit flags S2's quotation as absent from its source",
          audit["quotePresence"], audit["quotePresence"]["absent"] == ["S2"])
    check("A20", "citation audit confirms S1's quotation is present in its source",
          audit["quotePresence"]["present"], audit["quotePresence"]["present"] == ["S1"])
    check("A21", "citation audit deduplicates the shared DOI to one key and one removed entry",
          audit["deduplication"]["doiKeys"],
          audit["deduplication"]["distinctDoiKeys"] == 1
          and audit["deduplication"]["duplicateEntriesRemoved"] == 1
          or (audit["summaryCounts"]["distinctDoiKeys"] == 1
              and audit["summaryCounts"]["duplicateEntries"] == 1))
    check("A22", "citation audit labels the DOI unresolved and does not call it verified literature",
          {"scope": audit["scope"]["doi_resolution_attempted"],
           "verified": audit["verificationStatus"]["verifiedRealLiterature"]},
          audit["scope"]["doi_resolution_attempted"] is False
          and audit["verificationStatus"]["verifiedRealLiterature"] is False)
    check("A23", "citation audit records the retraction check as not run rather than passed",
          audit["summaryCounts"]["retractionChecksRun"], audit["summaryCounts"]["retractionChecksRun"] == 0)

    check("A24", "the input CSV bytes are unchanged from the delivered content",
          {"sha256": stats["input"]["sha256"][:16] + "...", "bytes": stats["input"]["bytes"]},
          stats["input"]["bytes"] == 82
          and stats["input"]["sha256"] == "d6687cb19e9460557aa85ef5854fb6056579d7ab375e4feeaef61a84e5a5567d")

    all_results = results + extra
    return all_results


def render_report(all_assertions, stats, scope, facts, audit, extra_lines):
    lines = []
    lines.append("Bounded local method test — executed assertion record")
    lines.append("=" * 64)
    lines.append("generated: {}".format(utc_now()))
    lines.append("input: input.csv  sha256 d6687cb19e9460557aa85ef5854fb6056579d7ab375e4feeaef61a84e5a5567d (82 bytes)")
    lines.append("data status: SYNTHETIC teaching table. Not patient data. No external lookup performed.")
    lines.append("")
    lines.append("How to re-run")
    lines.append("-" * 64)
    lines.append("python3 verify_methods.py --input input.csv --outdir .     # rewrites all four artifacts")
    lines.append("python3 data-profile.py input.csv --json data-profile.json --markdown data-profile.md")
    lines.append("")
    lines.append("Assertions")
    lines.append("-" * 64)
    failed = 0
    for a in all_assertions:
        mark = "PASS" if a["passed"] else "FAIL"
        if not a["passed"]:
            failed += 1
        lines.append("[{}] {}  {}".format(mark, a["id"], a["claim"]))
        obs = a.get("observed")
        rendered = json.dumps(obs, ensure_ascii=False, default=str)
        if len(rendered) > 220:
            rendered = rendered[:217] + "..."
        lines.append("       observed: {}".format(rendered))
    lines.append("")
    lines.append("{} of {} assertions passed; {} failed.".format(
        len(all_assertions) - failed, len(all_assertions), failed))
    lines.append("")
    lines.append("Denominator chain (from stats.json)")
    lines.append("-" * 64)
    d = stats["denominators"]
    lines.append("delivered rows                 : {}".format(d["originalRowDenominator"]))
    lines.append("rows with baseline AND outcome : {}".format(d["completePairRowDenominator"]))
    lines.append("distinct complete observations : {}".format(d["uniqueCompletePairObservationDenominator"]))
    lines.append("exact-duplicate groups         : {}".format(len(stats["duplicateObservations"]["exactDuplicateGroups"])))
    lines.append("missing: baseline {}, outcome {}".format(
        stats["missingness"]["baseline"]["blankCells"], stats["missingness"]["outcome"]["blankCells"]))
    lines.append("")
    lines.append("Estimand separation")
    lines.append("-" * 64)
    e = stats["estimand"]
    lines.append("E1 original-row     n={}  mean change={}".format(
        e["E1_original_row"]["n"], e["E1_original_row"]["meanChange"]))
    lines.append("E2 deduplicated     n={}  mean change={}".format(
        e["E2_deduplicated_unique_observation"]["n"],
        e["E2_deduplicated_unique_observation"]["meanChange"]))
    lines.append("per-group unique-observation changes: " + ", ".join(
        "{} -> {}".format(g, stats["analysis"]["changesByGroupUniqueObservationLevel"][g]["changeValues"])
        for g in sorted(stats["analysis"]["changesByGroupUniqueObservationLevel"])))
    lines.append("p value reported: no ({} )".format(stats["hypothesisTesting"]["reason"][:60] + "..."))
    lines.append("")
    lines.append("Notes carried by this run")
    lines.append("-" * 64)
    for line in extra_lines:
        lines.append("* " + line)
    lines.append("")
    lines.append("Files")
    lines.append("-" * 64)
    lines.append("input.csv                 the frozen synthetic input, bytes unchanged")
    lines.append("scope.json                dataset-research-scoping output")
    lines.append("stats.json                statistical-analysis output")
    lines.append("source-facts.json         source-understanding output")
    lines.append("citation-audit.json       citation-integrity output")
    lines.append("verification-report.txt   this record")
    lines.append("verify_methods.py         the script that produced all of the above")
    lines.append("data-profile.py, data-profile.json, data-profile.md   mechanical profile of the input")
    return "\n".join(lines) + "\n"


# --------------------------------------------------------------------------
def main() -> int:
    global BODY_TEXT, facts_source_text
    ap = argparse.ArgumentParser()
    ap.add_argument("--input", default="input.csv")
    ap.add_argument("--outdir", default=".")
    args = ap.parse_args()

    src = Path(args.input)
    out = Path(args.outdir)
    raw, text, header, body = load(src)
    BODY_TEXT = text
    facts_source_text = text

    stats = build_stats(header, body)
    scope = build_scope(header, body, stats)
    facts = build_source_facts(text, header, body)
    audit = build_citation_audit()

    all_assertions = run_assertions(stats, scope, facts, audit)
    stats["assertions"] = [a for a in all_assertions if a["id"].startswith("A") and a["id"][1:].isdigit()]
    stats["assertionsAllPassed"] = all(a["passed"] for a in all_assertions)

    notes = [
        "No external search, no DOI lookup and no full-text retrieval was performed; the evidence map is recorded as not_run.",
        "The dataset-semantics read/write operation is not exposed in this session, so no prior interpretation was read and none was recorded.",
        "Only the four requested method artifacts were produced; no product-level package was submitted.",
        "Group labels A and B are undocumented and no allocation mechanism is recorded in the data, so nothing here supports a randomized or causal reading.",
    ]

    def dump(name, obj):
        (out / name).write_text(json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=False) + "\n", encoding="utf-8")

    dump("stats.json", stats)
    dump("scope.json", scope)
    dump("source-facts.json", facts)
    dump("citation-audit.json", audit)
    (out / "verification-report.txt").write_text(
        render_report(all_assertions, stats, scope, facts, audit, notes), encoding="utf-8")

    # the input must still be byte-identical
    after = src.read_bytes()
    assert after == raw, "input.csv was modified by this run"
    print("wrote stats.json, scope.json, source-facts.json, citation-audit.json, verification-report.txt")
    print("assertions: {} passed / {} total".format(
        sum(1 for a in all_assertions if a["passed"]), len(all_assertions)))
    return 0 if all(a["passed"] for a in all_assertions) else 1


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        traceback.print_exc()
        sys.exit(2)

