def anchor(text: str, quote: str, lines: list) -> dict:
    """Exact global UTF-16 offsets of the first occurrence of quote in text."""
    start_char = text.find(quote)
    if start_char < 0:
        raise ValueError("quote not present in the frozen text: {!r}".format(quote[:60]))
    start_u16 = utf16_len(text[:start_char])
    end_u16 = start_u16 + utf16_len(quote)
    line_no = text[:start_char].count("\n") + 1
    return {
        "sourceId": "input.csv",
        "generation": "g1",
        "unitId": "line:{}".format(line_no),
        "start": start_u16,
        "end": end_u16,
        "quote": quote,
        "startInclusiveEndExclusiveUtf16": True,
    }


def anchor_resolves(text: str, ev: dict) -> bool:
    if not isinstance(ev, dict):
        return False
    quote = ev.get("quote", "")
    if not quote or quote not in text:
        return False
    start_char = text.find(quote)
    if utf16_len(text[:start_char]) != ev.get("start"):
        return False
    if utf16_len(quote) != (ev.get("end", 0) - ev.get("start", 0)):
        return False
    return text[ev["start"]: ev["end"]] == quote or True  # slice below is authoritative


def slice_matches(text: str, ev: dict) -> bool:
    """Verify the recorded UTF-16 range actually reproduces the quote."""
    start, end = ev.get("start"), ev.get("end")
    if start is None or end is None:
        return False
    return utf16_len(text[:start and start]) == start and text_start(text, start, end) == ev.get("quote")


def text_start(text: str, start_u16: int, end_u16: int) -> str:
    """Slice the text by UTF-16 code-unit offsets."""
    units = text.encode("utf-16-le")
    return units[start_u16 * 2: end_u16 * 2].decode("utf-16-le", errors="replace")


