def fisher_exact(a: int, b: int, c: int, d: int):
    """Two-sided and one-sided Fisher exact p for table [[a,b],[c,d]]."""
    n1, n2 = a + b, c + d
    k = a + c
    total = n1 + n2

    def p_of(x):
        return (math.comb(n1, x) * math.comb(n2, k - x)) / math.comb(total, k)

    observed = p_of(a)
    two_sided = 0.0
    one_sided = 0.0
    for x in range(max(0, k - n2), min(k, n1) + 1):
        p = p_of(x)
