def anchor(text: str, quote: str, lines: list) -> dict:
    """Exact global UTF-16 offsets of the first occurrence of quote in text."""
    start_char = text.find(quote)
    if start_char < 0:
        raise ValueError("quote not present in the frozen text: {!r}".format(quote[:60]))
    start_u16 = utf16_len(text[:start_char])
    end_u16 = start_u16 + utf16_len(quote)
    line_no = text[:start_char].count("\n") + 1
    return {
