    if utf16_len(quote) != (ev.get("end", 0) - ev.get("start", 0)):
        return False
    return text[ev["start"]: ev["end"]] == quote or True  # slice below is authoritative


def slice_matches(text: str, ev: dict) -> bool:
    """Verify the recorded UTF-16 range actually reproduces the quote."""
    start, end = ev.get("start"), ev.get("end")
    if start is None or end is None:
        return False
    return utf16_len(text[:start and start]) == start and text_start(text, start, end) == ev.get("quote")


def text_start(text: str, start_u16: int, end_u16: int) -> str:
    """Slice the text by UTF-16 code-unit offsets."""
    units = text.encode("utf-16-le")
    return units[start_u16 * 2: end_u16 * 2].decode("utf-16-le", errors="replace")


